import {ToolRegistry} from './registry.js';

it('returns a required location rejection before execution [specs/hal-engine-tool-input-validation/spec.md#3]', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather forecast',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    async input => JSON.stringify(input)
  );

  const response = await registry.execute('weather', {});

  expect(response.result).toMatch(/required.*location|location.*required/);
});
EOF
